GUARD_SHA256 = "e3733379da5e0cde84573f3279d265c91e16eceb8c94aeeda8983b51031216fe"

def main():
    assert sys.flags.isolated and sys.dont_write_bytecode and sys.pycache_prefix is None
    assert sys.version_info[:3] == (3,12,10)
    root=Path(__file__).absolute().parents[3]
    helper=root/'docs/intelligence/identity/run_qualification.py'
    for path in (helper,*helper.parents):
        info=path.lstat()
        assert not path.is_symlink() and not getattr(info,'st_file_attributes',0)&1024
    raw=helper.read_bytes()
    assert hashlib.sha256(raw).hexdigest()==GUARD_SHA256
    guard={'__name__':'owned_source_inventory','__file__':str(helper)}
    exec(compile(raw,str(helper),'exec'),guard)
    assert guard['git'](root,'rev-parse','HEAD').decode().strip()==os.environ['EXPECTED_HEAD']
    before=guard['inventory'](root)
    # This path configures only test source provisioning, never a capability.
    os.environ['A4_COMPONENT_ROOT']=str(root)
    assert os.environ.get('GRID_GATEWAY_SOURCE_ROOT'), 'PINNED_GRID_SOURCE_REQUIRED'
    sys.path.insert(0,str(root))
    suite=unittest.TestSuite()
    for folder,pattern,top in [('tests','test_intelligence_gateway.py',None),('tests','test_gateway_identity.py',None),('tests/gateway_runtime','test_*.py',None),('tests/storage','test*.py','tests'),('tests/storage/gateway_disclosure','test_*.py',None)]:
        suite.addTests(unittest.TestLoader().discover(str(root/folder),pattern=pattern,top_level_dir=None if top is None else str(root/top)))
    def ids(value):
        result=[]
        for test in value:
            result.extend(ids(test) if isinstance(test,unittest.TestSuite) else [test.id()])
        return result
    actual=ids(suite)
    assert len(actual)==len(set(actual))==len(REQUIRED) and sorted(actual)==REQUIRED
    result=None;after=None
    try:
        result=unittest.TextTestRunner(verbosity=2).run(suite)
        assert result.wasSuccessful() and result.testsRun==len(REQUIRED) and not result.skipped
    finally:
        try:
            after=guard['inventory'](root)
            assert before==after
        finally:
            receipt=dict(source_head=os.environ['EXPECTED_HEAD'],python=sys.version,tests=REQUIRED,
                tests_run=None if result is None else result.testsRun,
                failures=None if result is None else len(result.failures),errors=None if result is None else len(result.errors),
                skips=None if result is None else len(result.skipped),source_before=before,source_after=after,
                scope='DISPOSABLE_AUTHENTICATED_READ_ONLY_NOT_JOB_VERTICAL_E2E',
                root_read_scenario='ACTUAL_LOOPBACK_TLS_AND_OWN_IMMUTABLE_SYNTHETIC_OBJECTS',
                grid_module_source='f19f7feee0f63da34a20607a8cae59191180aa7c',
                native_human_authentication=False,production=False,physical=False,job_admission=False)
            (Path(os.environ['RUNNER_TEMP'])/'gateway-read-qualification.json').write_bytes((json.dumps(receipt,indent=2)+'\n').encode())

if __name__=='__main__':main()
